import { App, Modal, Notice, TFile, prepareFuzzySearch } from "obsidian";
import { BrainClient, Memory } from "./brain";
import type { BrainSettings } from "./settings";
import type { IndexState } from "./indexer";

interface SearchState {
	query: string;
	results: Memory[];
	loading: boolean;
	error: string | null;
	selected: number;
}

/**
 * Cmd+Shift+B — semantic search against the brain.
 * Falls back to local fuzzy ranking if the brain is unavailable, so the
 * command still feels responsive without a backend.
 */
export class BrainSearchModal extends Modal {
	private inputEl!: HTMLInputElement;
	private resultsEl!: HTMLElement;
	private statusEl!: HTMLElement;
	private state: SearchState = {
		query: "",
		results: [],
		loading: false,
		error: null,
		selected: 0,
	};
	private debounceHandle: number | null = null;
	private generation = 0;

	constructor(
		app: App,
		private brain: BrainClient,
		private settings: BrainSettings,
		private indexState: IndexState,
		private seed?: string,
	) {
		super(app);
	}

	onOpen(): void {
		const { contentEl, modalEl } = this;
		modalEl.addClass("obsidian-brain-search-modal");
		contentEl.empty();
		contentEl.createEl("div", { cls: "brain-search-title", text: "Brain semantic search" });

		this.inputEl = contentEl.createEl("input", {
			type: "text",
			cls: "brain-search-input",
			attr: { placeholder: "Search the brain (DiskANN)…", spellcheck: "false" },
		});
		this.statusEl = contentEl.createEl("div", { cls: "brain-search-status" });
		this.resultsEl = contentEl.createEl("div", { cls: "brain-search-results" });

		this.inputEl.addEventListener("input", () => {
			this.state.query = this.inputEl.value;
			this.state.selected = 0;
			this.scheduleSearch();
		});
		this.inputEl.addEventListener("keydown", (e) => this.onKey(e));
		setTimeout(() => {
			this.inputEl.focus();
			if (this.seed) {
				this.inputEl.value = this.seed;
				this.inputEl.setSelectionRange(
					this.seed.length,
					this.seed.length,
				);
				this.state.query = this.seed;
				void this.runSearch();
			}
		}, 0);

		this.render();
	}

	onClose(): void {
		if (this.debounceHandle) window.clearTimeout(this.debounceHandle);
		this.contentEl.empty();
	}

	private scheduleSearch(): void {
		if (this.debounceHandle) window.clearTimeout(this.debounceHandle);
		this.debounceHandle = window.setTimeout(() => this.runSearch(), 180);
	}

	private async runSearch(): Promise<void> {
		const q = this.state.query.trim();
		if (!q) {
			this.state.results = [];
			this.state.error = null;
			this.render();
			return;
		}
		const { query, category } = parseCategoryPrefix(q);
		const gen = ++this.generation;
		this.state.loading = true;
		this.state.error = null;
		this.render();
		try {
			const resp = await this.brain.search(
				query || q,
				this.settings.searchLimit,
			);
			if (gen !== this.generation) return;
			this.state.results = category
				? resp.results.filter((r) => r.category === category)
				: resp.results;
		} catch (e) {
			if (gen !== this.generation) return;
			this.state.error = (e as Error).message;
			this.state.results = this.localFallback(query || q);
		} finally {
			if (gen === this.generation) {
				this.state.loading = false;
				this.render();
			}
		}
	}

	private localFallback(q: string): Memory[] {
		const match = prepareFuzzySearch(q);
		const files = this.app.vault.getMarkdownFiles();
		const scored: Array<{ score: number; file: TFile }> = [];
		for (const f of files) {
			const r = match(f.path);
			if (r) scored.push({ score: r.score, file: f });
		}
		scored.sort((a, b) => b.score - a.score);
		return scored.slice(0, this.settings.searchLimit).map<Memory>((s) => ({
			id: `local:${s.file.path}`,
			category: "local",
			content_hash: "",
			created_at: Math.floor(s.file.stat.mtime / 1000),
			score: s.score,
			content: s.file.basename,
		}));
	}

	private onKey(e: KeyboardEvent): void {
		if (e.key === "ArrowDown") {
			e.preventDefault();
			this.state.selected = Math.min(
				this.state.results.length - 1,
				this.state.selected + 1,
			);
			this.render();
		} else if (e.key === "ArrowUp") {
			e.preventDefault();
			this.state.selected = Math.max(0, this.state.selected - 1);
			this.render();
		} else if (e.key === "Enter") {
			e.preventDefault();
			const r = this.state.results[this.state.selected];
			if (r) void this.activate(r);
		} else if (e.key === "Escape") {
			this.close();
		}
	}

	private async activate(mem: Memory): Promise<void> {
		// Prefer opening a note if we know which file this memory came from.
		const path = mem.id.startsWith("local:")
			? mem.id.slice("local:".length)
			: this.indexState.idToPath[mem.id];
		if (path) {
			const file = this.app.vault.getAbstractFileByPath(path);
			if (file instanceof TFile) {
				await this.app.workspace.getLeaf(false).openFile(file);
				this.close();
				return;
			}
		}
		// Otherwise, show a preview pane inline.
		this.showPreview(mem);
	}

	private async showPreview(mem: Memory): Promise<void> {
		try {
			if (!mem.content) {
				const full = await this.brain.getMemory(mem.id);
				mem = { ...mem, content: full.content };
			}
		} catch {
			/* ignore */
		}
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createEl("div", {
			cls: "brain-search-title",
			text: `${mem.category} — ${mem.id.slice(0, 12)}`,
		});
		const pre = contentEl.createEl("pre", { cls: "brain-search-preview" });
		pre.createEl("code", { text: mem.content ?? "(no content)" });
		const close = contentEl.createEl("button", {
			cls: "mod-cta",
			text: "Back to results",
		});
		close.onclick = () => {
			this.onOpen();
			this.inputEl.value = this.state.query;
		};
	}

	private render(): void {
		const { resultsEl, statusEl, state } = this;
		statusEl.empty();
		resultsEl.empty();
		if (state.loading) statusEl.setText("Searching…");
		else if (state.error) statusEl.setText(`Brain offline — fuzzy fallback (${state.error})`);
		else if (state.query && state.results.length === 0)
			statusEl.setText("No results");
		else if (state.query)
			statusEl.setText(`${state.results.length} result${state.results.length === 1 ? "" : "s"}`);

		state.results.forEach((r, i) => {
			const row = resultsEl.createEl("div", {
				cls: `brain-search-row${i === state.selected ? " selected" : ""}`,
			});
			const cat = row.createEl("span", { cls: "brain-search-category", text: r.category });
			const meta = row.createEl("span", { cls: "brain-search-meta" });
			const score = r.score !== undefined ? r.score.toFixed(3) : "—";
			meta.setText(`score ${score}`);
			const snippet =
				(r.content ?? "").replace(/\s+/g, " ").trim().slice(0, 140) ||
				r.id.slice(0, 16);
			row.createEl("div", { cls: "brain-search-snippet", text: snippet });
			cat.style.setProperty("--brain-category", hashColor(r.category));
			row.addEventListener("click", () => void this.activate(r));
			row.addEventListener("mousemove", () => {
				this.state.selected = i;
				this.render();
			});
		});
		if (!state.query) {
			statusEl.setText("Type to search. Enter opens, Esc closes.");
		}
	}
}

function hashColor(s: string): string {
	let h = 0;
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
	const hue = Math.abs(h) % 360;
	return `hsl(${hue}, 55%, 55%)`;
}

/**
 * Parse a `category:<token> <rest of query>` prefix. Returns the
 * extracted category (or null) and the remaining query text. Supports
 * quoted categories: `category:"design patterns" semantic search`.
 */
export function parseCategoryPrefix(q: string): {
	query: string;
	category: string | null;
} {
	const m = /^category:(?:"([^"]+)"|(\S+))\s*(.*)$/i.exec(q);
	if (!m) return { query: q, category: null };
	return { category: (m[1] ?? m[2]).trim(), query: (m[3] ?? "").trim() };
}

export async function quickSearchAndOpen(
	app: App,
	brain: BrainClient,
	settings: BrainSettings,
	indexState: IndexState,
): Promise<void> {
	const active = app.workspace.getActiveFile();
	if (!active) {
		new Notice("Open a note first to find related memories");
		return;
	}
	const raw = await app.vault.read(active);
	try {
		const resp = await brain.search(raw.slice(0, 2000), settings.relatedLimit);
		new Notice(`Brain: ${resp.results.length} related memories — see side panel`);
	} catch (e) {
		new Notice(`Brain search failed: ${(e as Error).message}`);
	}
	// Help the user — make sure the related view is visible.
	const leaves = app.workspace.getLeavesOfType("obsidian-brain-related");
	if (leaves[0]) app.workspace.revealLeaf(leaves[0]);
	void indexState; // retained for future ranking tweaks
}

/*
 * Real Obsidian E2E — gated on $OBSIDIAN_E2E=1 because it downloads a real
 * Obsidian AppImage on first run and drives a real windowed app. Uses
 * xvfb-run automatically when no $DISPLAY is set (requires xvfb installed).
 *
 * Typical usage (after `cargo build --release -p mcp-brain-server --features local`):
 *
 *   sudo apt install xvfb
 *   OBSIDIAN_E2E=1 npm test -- tests/e2e
 */

import { describe, expect, it } from "vitest";
import { resolve } from "node:path";
import { runObsidianE2E } from "./obsidian-runner";

const RUN = process.env.OBSIDIAN_E2E === "1";

describe.skipIf(!RUN)("real Obsidian + obsidian-brain plugin (E2E)", () => {
	it(
		"loads plugin, indexes a note, searches, bulk syncs, applies graph overlay",
		async () => {
			const result = await runObsidianE2E({
				pluginDir: resolve(__dirname, "..", ".."),
			});
			const failed = result.report.checks.filter((c) => !c.ok);
			if (failed.length > 0) {
				throw new Error(
					"harness reported failures:\n" +
						failed.map((c) => `  ✗ ${c.name}: ${c.detail}`).join("\n"),
				);
			}
			// Checks:
			//   1 brain plugin loaded
			//   2 base commands registered
			//   3 status bar populated
			//   4 index current note
			//   5 brain.search roundtrip
			//   6 bulk sync
			//   7 graph overlay
			//   8 pi commands registered
			//   9 pi status roundtrip (only when BRAIN_API_KEY plumbed)
			//  10 phase-4 commands registered (qa/ops/selection/publish/recall/queue)
			//  11 offline queue API accessible
			const minExpected = process.env.BRAIN_API_KEY ? 11 : 10;
			expect(result.report.passed).toBeGreaterThanOrEqual(minExpected);
		},
		300_000,
	);
});

/*
 * Real pi.ruv.io integration — gated on `BRAIN_API_KEY` because the
 * endpoints require a bearer token that isn't appropriate to commit.
 * Asserts the exact response shapes PiClient parses.
 */

import { describe, expect, it } from "vitest";

const token = [REDACTED] ?? "";
const base = process.env.PI_URL ?? "https://pi.ruv.io";
const RUN = !!token;

async function bearerJSON<T>(path: string): Promise<T> {
	const resp = await fetch(base.replace(/\/$/, "") + path, {
		headers: { Authorization: `Bearer ${token}` },
	});
	if (!resp.ok) {
		throw new Error(`${path} → ${resp.status}: ${await resp.text()}`);
	}
	return (await resp.json()) as T;
}

describe.skipIf(!RUN)("protocol: live pi.ruv.io contract", () => {
	it("GET /v1/status — returns global stats (no auth)", async () => {
		const resp = await fetch(base.replace(/\/$/, "") + "/v1/status");
		expect(resp.ok).toBe(true);
		const s = (await resp.json()) as {
			total_memories: number;
			graph_edges: number;
			embedding_dim: number;
			drift_status: string;
		};
		expect(typeof s.total_memories).toBe("number");
		expect(s.total_memories).toBeGreaterThan(0);
		expect(typeof s.graph_edges).toBe("number");
		expect(s.embedding_dim).toBeGreaterThan(0);
		expect(typeof s.drift_status).toBe("string");
	});

	it("GET /v1/memories/list — bearer-gated, returns memory[] with required fields", async () => {
		const body = await bearerJSON<{
			memories: Array<{ id: string; category: string; content: string; title?: string; tags?: string[] }>;
			total_count: number;
			offset: number;
			limit: number;
		}>("/v1/memories/list?limit=3");
		expect(body.total_count).toBeGreaterThan(0);
		expect(Array.isArray(body.memories)).toBe(true);
		expect(body.memories.length).toBeGreaterThan(0);
		const m = body.memories[0];
		expect(typeof m.id).toBe("string");
		expect(m.id.length).toBeGreaterThan(8);
		expect(typeof m.category).toBe("string");
		expect(typeof m.content).toBe("string");
	});

	it("GET /v1/memories/search — bearer-gated, returns score-ranked array", async () => {
		const results = (await bearerJSON<
			| Array<{ id: string; category: string; content: string; score?: number }>
			| { memories: Array<{ id: string; category: string; content: string; score?: number }> }
		>("/v1/memories/search?q=hnsw&limit=3")) as unknown;
		const arr = Array.isArray(results)
			? results
			: (results as { memories: unknown[] }).memories;
		expect(Array.isArray(arr)).toBe(true);
		expect(arr.length).toBeGreaterThan(0);
		const first = arr[0] as { id: string; score?: number };
		expect(typeof first.id).toBe("string");
		// score may be absent on some memory types but if present should be a number
		if ("score" in first && first.score !== undefined) {
			expect(typeof first.score).toBe("number");
		}
	});

	it("bearer is required", async () => {
		const resp = await fetch(base.replace(/\/$/, "") + "/v1/memories/list?limit=1");
		expect(resp.status).toBe(401);
	});

	it("POST /v1/memories write-through (slow ~20s) returns created shape", async () => {
		const resp = await fetch(base.replace(/\/$/, "") + "/v1/memories", {
			method: "POST",
			headers: {
				"content-type": "application/json",
				Authorization: `Bearer ${token}`,
			},
			body: JSON.stringify({
				category: "pattern",
				content:
					"obsidian-brain plugin protocol test — delete-safe placeholder",
				title: "obsidian-brain protocol probe",
				tags: ["probe", "obsidian-brain"],
			}),
		});
		expect([200, 201]).toContain(resp.status);
		const body = (await resp.json()) as {
			id: string;
			quality_score: number;
			witness_hash: string;
			rvf_segments?: number;
		};
		expect(body.id).toMatch(
			/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/,
		);
		expect(typeof body.quality_score).toBe("number");
		expect(typeof body.witness_hash).toBe("string");
	}, 40_000);

	it("POST /v1/memories rejects unknown category with 422", async () => {
		const resp = await fetch(base.replace(/\/$/, "") + "/v1/memories", {
			method: "POST",
			headers: {
				"content-type": "application/json",
				Authorization: `Bearer ${token}`,
			},
			body: JSON.stringify({
				category: "totally-bogus-category-does-not-exist",
				content: "whatever",
				title: "unused",
				tags: [],
			}),
		});
		expect(resp.status).toBe(422);
	});
});

/*
 * Protocol integration test — drives the REAL `mcp-brain-server-local`
 * subprocess with the REAL HTTP contract the Obsidian plugin depends on.
 *
 * The plugin's BrainClient is a thin wrapper around `obsidian.requestUrl`,
 * so what matters is that the server's response shapes match the fields the
 * client pulls out. This test asserts those shapes directly against a live
 * brain. No mocks.
 */

import {
	afterAll,
	beforeAll,
	describe,
	expect,
	it,
} from "vitest";
import { ChildProcess, spawn } from "node:child_process";
import { mkdtempSync, rmSync, existsSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createServer, Server } from "node:http";
import { setTimeout as sleep } from "node:timers/promises";
import { AddressInfo } from "node:net";

interface Harness {
	brainUrl: string;
	embedderUrl: string;
	stop: () => Promise<void>;
}

const DIM = 16; // keep deterministic vectors short — brain accepts any dim

async function startEmbedder(): Promise<{ url: string; server: Server }> {
	let tick = 0;
	const server = createServer((req, res) => {
		if (!req.url || req.method !== "POST" || !req.url.startsWith("/embed")) {
			res.writeHead(404).end();
			return;
		}
		const chunks: Buffer[] = [];
		req.on("data", (c) => chunks.push(c));
		req.on("end", () => {
			try {
				const body = JSON.parse(Buffer.concat(chunks).toString("utf8")) as {
					texts: string[];
				};
				const vectors = body.texts.map((t) => {
					tick++;
					const v = new Array<number>(DIM).fill(0);
					for (let i = 0; i < t.length; i++) {
						v[i % DIM] += t.charCodeAt(i) / 256;
					}
					v[0] += tick * 0.0001;
					const norm = Math.sqrt(v.reduce((s, x) => s + x * x, 0)) || 1;
					return v.map((x) => x / norm);
				});
				res.writeHead(200, { "content-type": "application/json" });
				res.end(JSON.stringify({ vectors }));
			} catch (e) {
				res.writeHead(400).end(JSON.stringify({ error: (e as Error).message }));
			}
		});
	});
	await new Promise<void>((r) => server.listen(0, "127.0.0.1", r));
	const addr = server.address() as AddressInfo;
	return { url: `http://127.0.0.1:${addr.port}`, server };
}

async function waitForHealth(url: string, timeoutMs: number): Promise<void> {
	const deadline = Date.now() + timeoutMs;
	let lastErr: unknown = null;
	while (Date.now() < deadline) {
		try {
			const r = await fetch(url + "/health");
			if (r.ok) return;
		} catch (e) {
			lastErr = e;
		}
		await sleep(100);
	}
	throw new Error(
		`brain did not come up within ${timeoutMs}ms: ${(lastErr as Error | null)?.message ?? ""}`,
	);
}

async function pickPort(): Promise<number> {
	// Grab an OS-assigned port, close immediately, reuse the number.
	const s = createServer();
	await new Promise<void>((r) => s.listen(0, "127.0.0.1", r));
	const port = (s.address() as AddressInfo).port;
	await new Promise<void>((r) => s.close(() => r()));
	return port;
}

function resolveBrainBinary(): string {
	const envBin = process.env.RUVBRAIN_BIN;
	if (envBin && existsSync(envBin)) return envBin;
	// Repo-relative default: ../../target/release/mcp-brain-server-local
	const fromRepo = join(
		__dirname,
		"..",
		"..",
		"..",
		"..",
		"target",
		"release",
		"mcp-brain-server-local",
	);
	if (existsSync(fromRepo)) return fromRepo;
	throw new Error(
		"mcp-brain-server-local not found. Build with:\n" +
			"  cargo build --release -p mcp-brain-server --features local --bin mcp-brain-server-local\n" +
			"or set RUVBRAIN_BIN=/path/to/binary",
	);
}

async function startBrain(embedderUrl: string): Promise<Harness> {
	const bin = resolveBrainBinary();
	const port = await pickPort();
	const dir = mkdtempSync(join(tmpdir(), "brain-test-"));
	const db = join(dir, "brain.sqlite");
	const blobs = join(dir, "blobs");
	const child: ChildProcess = spawn(bin, [], {
		env: {
			...process.env,
			RUVBRAIN_PORT: String(port),
			RUVBRAIN_DB: db,
			RUVBRAIN_BLOBS: blobs,
			RUVBRAIN_STORE: "rvf",
			RUVBRAIN_EMBEDDER_URL: embedderUrl,
			RUST_LOG: process.env.RUST_LOG ?? "warn",
		},
		stdio: ["ignore", "pipe", "pipe"],
	});
	const stderr: string[] = [];
	child.stderr?.on("data", (d: Buffer) => stderr.push(d.toString()));
	child.stdout?.on("data", () => undefined);

	const brainUrl = `http://127.0.0.1:${port}`;
	try {
		await waitForHealth(brainUrl, 10_000);
	} catch (e) {
		try {
			child.kill("SIGKILL");
		} catch {
			/* ignore */
		}
		throw new Error(
			`${(e as Error).message}\nbrain stderr:\n${stderr.join("")}`,
		);
	}
	return {
		brainUrl,
		embedderUrl,
		stop: async () => {
			child.kill("SIGTERM");
			await new Promise<void>((r) => {
				const t = setTimeout(() => {
					try {
						child.kill("SIGKILL");
					} catch {
						/* ignore */
					}
					r();
				}, 2000);
				child.once("exit", () => {
					clearTimeout(t);
					r();
				});
			});
			try {
				rmSync(dir, { recursive: true, force: true });
			} catch {
				/* ignore */
			}
		},
	};
}

interface BrainSearchResult {
	results: Array<{
		id: string;
		score: number;
		category: string;
		content_hash: string;
		created_at: number;
		content?: string;
	}>;
	query_vector_dim: number;
}

interface CreateMemoryResult {
	id: string;
	content_hash: string;
	created_at: number;
}

async function postJSON<T>(
	url: string,
	body: unknown,
	expectStatus = 200,
): Promise<T> {
	const r = await fetch(url, {
		method: "POST",
		headers: { "content-type": "application/json" },
		body: JSON.stringify(body),
	});
	const text = await r.text();
	if (r.status !== expectStatus) {
		throw new Error(`POST ${url} → ${r.status} (expected ${expectStatus}): ${text}`);
	}
	return JSON.parse(text) as T;
}

async function getJSON<T>(url: string): Promise<T> {
	const r = await fetch(url);
	const text = await r.text();
	if (!r.ok) throw new Error(`GET ${url} → ${r.status}: ${text}`);
	return JSON.parse(text) as T;
}

describe("protocol: real mcp-brain-server-local ↔ plugin contract", () => {
	let harness: Harness;
	let embedder: { url: string; server: Server };

	beforeAll(async () => {
		embedder = await startEmbedder();
		harness = await startBrain(embedder.url);
	}, 60_000);

	afterAll(async () => {
		if (harness) await harness.stop();
		if (embedder)
