import { App, Modal, Notice } from "obsidian";
import type { Indexer, ProgressReporter } from "./indexer";

export class BulkSyncModal extends Modal {
	private cancelled = false;
	private startBtn!: HTMLButtonElement;
	private cancelBtn!: HTMLButtonElement;
	private progressBar!: HTMLElement;
	private progressLabel!: HTMLElement;
	private detail!: HTMLElement;
	private running = false;

	constructor(
		app: App,
		private indexer: Indexer,
	) {
		super(app);
	}

	onOpen(): void {
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createEl("h2", { text: "Bulk-sync vault → brain" });
		contentEl.createEl("p", {
			text:
				"Indexes every markdown note matching your include/exclude filters. " +
				"Unchanged notes are skipped automatically.",
		});

		const bar = contentEl.createEl("div", { cls: "brain-bulk-progress" });
		this.progressBar = bar.createEl("div", { cls: "brain-bulk-progress-fill" });
		this.progressLabel = contentEl.createEl("div", {
			cls: "brain-bulk-progress-label",
			text: "Idle",
		});
		this.detail = contentEl.createEl("div", { cls: "brain-bulk-progress-detail" });

		const buttons = contentEl.createEl("div", { cls: "brain-bulk-buttons" });
		this.startBtn = buttons.createEl("button", { text: "Start", cls: "mod-cta" });
		this.cancelBtn = buttons.createEl("button", { text: "Close" });

		this.startBtn.addEventListener("click", () => void this.start());
		this.cancelBtn.addEventListener("click", () => {
			if (this.running) {
				this.cancelled = true;
				this.cancelBtn.setText("Cancelling…");
			} else {
				this.close();
			}
		});
	}

	onClose(): void {
		this.cancelled = true;
		this.contentEl.empty();
	}

	private async start(): Promise<void> {
		if (this.running) return;
		this.running = true;
		this.cancelled = false;
		this.startBtn.disabled = true;
		this.cancelBtn.setText("Cancel");
		const reporter: ProgressReporter = {
			update: (done, total, note) => {
				const pct = total === 0 ? 0 : Math.round((done / total) * 100);
				this.progressBar.style.width = `${pct}%`;
				this.progressLabel.setText(`${done} / ${total} (${pct}%)`);
				if (note) this.detail.setText(note);
			},
			cancelled: () => this.cancelled,
		};
		const started = Date.now();
		try {
			const result = await this.indexer.bulkSync(reporter);
			const elapsed = ((Date.now() - started) / 1000).toFixed(1);
			const msg =
				`Bulk sync done in ${elapsed}s — ` +
				`${result.indexed} indexed, ${result.skipped} skipped, ${result.failed} failed`;
			this.progressLabel.setText(msg);
			new Notice(msg);
		} catch (e) {
			const msg = `Bulk sync failed: ${(e as Error).message}`;
			this.progressLabel.setText(msg);
			new Notice(msg, 8000);
		} finally {
			this.running = false;
			this.startBtn.disabled = false;
			this.cancelBtn.setText("Close");
		}
	}
}

import { Notice, Plugin } from "obsidian";
import { BrainClient, BrainError } from "./brain";

/**
 * Persisted queue of pending POST /memories writes. Filled when the
 * brain is unreachable and drained on a periodic timer once health
 * comes back. Survives plugin reloads via data.json.
 *
 * Only applies to local-brain writes — pi.ruv.io writes are explicit
 * user actions and aren't queued.
 */
export interface QueuedMemory {
	category: string;
	content: string;
	queuedAt: number;
	/** Per-path deduping: one queued entry per vault path. */
	path?: string;
}

export interface OfflineQueueState {
	pending: QueuedMemory[];
}

export const EMPTY_QUEUE_STATE: OfflineQueueState = { pending: [] };

export class OfflineQueue {
	private timer: number | null = null;
	private draining = false;

	constructor(
		private plugin: Plugin,
		private brain: BrainClient,
		public state: OfflineQueueState,
		private onChange: () => void,
	) {}

	enqueue(entry: QueuedMemory): void {
		if (entry.path) {
			this.state.pending = this.state.pending.filter((q) => q.path !== entry.path);
		}
		this.state.pending.push(entry);
		this.onChange();
	}

	size(): number {
		return this.state.pending.length;
	}

	start(intervalMs = 30_000): void {
		if (this.timer) window.clearInterval(this.timer);
		this.timer = window.setInterval(() => void this.drain(), intervalMs);
	}

	stop(): void {
		if (this.timer) {
			window.clearInterval(this.timer);
			this.timer = null;
		}
	}

	/** Try to flush everything. Stops at the first network error. */
	async drain(): Promise<{ sent: number; failed: number }> {
		if (this.draining) return { sent: 0, failed: 0 };
		if (this.state.pending.length === 0) return { sent: 0, failed: 0 };
		this.draining = true;
		let sent = 0;
		let failed = 0;
		try {
			const remaining: QueuedMemory[] = [];
			for (const q of this.state.pending) {
				try {
					await this.brain.createMemory(q.category, q.content);
					sent++;
				} catch (e) {
					if (e instanceof BrainError && e.status === 0) {
						// Still offline — keep the rest queued.
						remaining.push(q);
						const idx = this.state.pending.indexOf(q);
						for (const later of this.state.pending.slice(idx + 1)) {
							remaining.push(later);
						}
						break;
					}
					// Hard rejection (422, 500, etc.) — drop it; we'd re-reject forever.
					failed++;
				}
			}
			this.state.pending = remaining;
			this.onChange();
			if (sent > 0) {
				new Notice(`Brain offline queue: replayed ${sent} pending write${sent === 1 ? "" : "s"}`);
			}
		} finally {
			this.draining = false;
		}
		return { sent, failed };
	}
}

/*
 * Client for the shared pi.ruv.io brain.
 *
 * Endpoints (per https://pi.ruv.io):
 *   GET  /v1/status                           — unauth, returns global stats
 *   GET  /v1/memories/list?limit=&offset=&category=   — Bearer, paginated list
 *   GET  /v1/memories/search?q=&limit=        — Bearer, semantic search (+score)
 */

import { requestUrl, RequestUrlResponse } from "obsidian";

export interface PiStatus {
	total_memories: number;
	total_contributors: number;
	graph_nodes: number;
	graph_edges: number;
	cluster_count: number;
	embedding_dim: number;
	drift_status: string;
	lora_epoch?: number;
}

export interface PiMemory {
	id: string;
	title?: string;
	content: string;
	category?: string;
	tags?: string[];
	score?: number;
	created_at?: string;
	contributor_id?: string;
}

export interface PiCreateMemoryResult {
	id: string;
	partition_id?: string | null;
	quality_score: number;
	witness_hash: string;
	rvf_segments?: number;
}

/**
 * Fixed enum accepted by pi.ruv.io's POST /v1/memories endpoint. Anything
 * outside this set must be submitted via the `custom` newtype variant.
 */
export const PI_CATEGORIES = [
	"architecture",
	"pattern",
	"solution",
	"convention",
	"security",
	"performance",
	"tooling",
	"debug",
	"sota",
	"discovery",
	"hypothesis",
	"cross_domain",
	"neural_architecture",
	"compression",
	"self_learning",
	"reinforcement_learning",
	"graph_intelligence",
	"distributed_systems",
	"edge_computing",
	"hardware_acceleration",
	"quantum",
	"neuromorphic",
	"bio_computing",
	"cognitive_science",
	"formal_methods",
	"geopolitics",
	"climate",
	"biomedical",
	"space",
	"finance",
	"meta_cognition",
	"benchmark",
	"consciousness",
	"information_decomposition",
] as const;

export type PiCategory = (typeof PI_CATEGORIES)[number] | { custom: string };

export function piCategory(raw: string): PiCategory {
	const known = PI_CATEGORIES.find((c) => c === raw);
	if (known) return known;
	return { custom: raw };
}

export interface PiSearchResult {
	memories: PiMemory[];
	total_count: number;
}

export class PiError extends Error {
	constructor(
		public status: number,
		message: string,
		public body?: unknown,
	) {
		super(message);
		this.name = "PiError";
	}
}

export class PiClient {
	constructor(
		public url: string,
		public token: string,
	) {}

	get configured(): boolean {
		return !!this.url && !!this.token;
	}

	private async req<T>(
		method: "GET" | "POST",
		path: string,
		body?: unknown,
	): Promise<T> {
		const base = this.url.replace(/\/$/, "");
		let resp: RequestUrlResponse;
		try {
			resp = await requestUrl({
				url: base + path,
				method,
				headers: this.token ? { Authorization: `Bearer ${this.token}` } : {},
				contentType: body ? "application/json" : undefined,
				body: body ? JSON.stringify(body) : undefined,
				throw: false,
			});
		} catch (e) {
			throw new PiError(0, `pi.ruv.io network error: ${(e as Error).message}`);
		}
		if (resp.status >= 400) {
			throw new PiError(resp.status, `pi.ruv.io ${path} → ${resp.status}`, resp.json ?? resp.text);
		}
		return resp.json as T;
	}

	async status(): Promise<PiStatus> {
		return this.req<PiStatus>("GET", "/v1/status");
	}

	async list(limit: number, offset = 0, category?: string): Promise<PiMemory[]> {
		const q = new URLSearchParams({
			limit: String(limit),
			offset: String(offset),
		});
		if (category) q.set("category", category);
		const resp = await this.req<{ memories?: PiMemory[] } | PiMemory[]>(
			"GET",
			`/v1/memories/list?${q.toString()}`,
		);
		if (Array.isArray(resp)) return resp;
		return resp.memories ?? [];
	}

	async search(query: string, limit: number): Promise<PiMemory[]> {
		const q = new URLSearchParams({ q: query, limit: String(limit) });
		const resp = await this.req<PiMemory[] | { memories?: PiMemory[] }>(
			"GET",
			`/v1/memories/search?${q.toString()}`,
		);
		if (Array.isArray(resp)) return resp;
		return resp.memories ?? [];
	}

	/**
	 * Publish a memory to pi.ruv.io. The server runs AIDefence, DP-noising
	 * and RVF segmentation on ingest so requests can take ~20s to return.
	 */
	async createMemory(
		category: PiCategory,
		content: string,
		title: string,
		tags: string[],
	): Promise<PiCreateMemoryResult> {
		return this.req<PiCreateMemoryResult>("POST", "/v1/memories", {
			category,
			content,
			title,
			tags,
		});
	}
}

import { App, Modal, Notice, requestUrl } from "obsidian";
import { BrainClient } from "./brain";
import type { BrainSettings } from "./settings";

/**
 * Surfaces the "second-tier" brain endpoints that were previously
 * unused by the plugin: /brain/workload, /brain/training-stats,
 * /learning/stats, /brain/checkpoint, /brain/export-pairs,
 * /brain/store_mode. One modal, read-only + two buttons.
 */
export class BrainOpsModal extends Modal {
	constructor(
		app: App,
		private brain: BrainClient,
		private settings: BrainSettings,
	) {
		super(app);
	}

	onOpen(): void {
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createEl("h2", { text: "Brain Ops" });
		contentEl.createEl("p", {
			cls: "brain-ops-hint",
			text: `Endpoint: ${this.settings.brainUrl}`,
		});
		const grid = contentEl.createEl("div", { cls: "brain-ops-grid" });
		const left = grid.createEl("div", { cls: "brain-ops-col" });
		const right = grid.createEl("div", { cls: "brain-ops-col" });

		const panels: Array<{
			title: string;
			path: string;
			el: HTMLElement;
			kind?: "left" | "right";
		}> = [
			{ title: "Store mode", path: "/brain/store_mode", el: left },
			{ title: "Index stats", path: "/brain/index_stats", el: left },
			{ title: "Learning stats", path: "/learning/stats", el: left },
			{ title: "Workload", path: "/brain/workload", el: right },
			{ title: "Training stats", path: "/brain/training-stats", el: right },
			{ title: "Info", path: "/brain/info", el: right },
		];
		for (const p of panels) {
			const card = p.el.createEl("div", { cls: "brain-ops-card" });
			card.createEl("h3", { text: p.title });
			const pre = card.createEl("pre", { cls: "brain-ops-pre", text: "loading…" });
			void this.loadInto(pre, p.path);
		}

		const actions = contentEl.createEl("div", { cls: "brain-ops-actions" });
		const checkpoint = actions.createEl("button", {
			cls: "mod-cta",
			text: "Checkpoint (WAL flush)",
		});
		checkpoint.addEventListener("click", () => void this.checkpoint());

		const exportPairs = actions.createEl("button", {
			text: "Export DPO pairs (JSONL)",
		});
		exportPairs.addEventListener("click", () => void this.exportPairs());
	}

	onClose(): void {
		this.contentEl.empty();
	}

	private async loadInto(target: HTMLElement, path: string): Promise<void> {
		try {
			const resp = await requestUrl({
				url: this.settings.brainUrl.replace(/\/$/, "") + path,
				method: "GET",
				throw: false,
			});
			if (resp.status >= 400) {
				target.setText(`HTTP ${resp.status}`);
				return;
			}
			target.setText(JSON.stringify(resp.json, null, 2));
		} catch (e) {
			target.setText(`error: ${(e as Error).message}`);
		}
	}

	private async checkpoint(): Promise<void> {
		try {
			const resp = await requestUrl({
				url: this.settings.brainUrl.replace(/\/$/, "") + "/brain/checkpoint",
				method: "POST",
				throw: false,
				contentType: "application/json",
				body: "{}",
			});
			if (resp.status >= 400) {
				new Notice(`Checkpoint failed: ${resp.status}`);
				return;
			}
			new Notice(`Checkpoint OK: ${JSON.stringify(resp.json)}`);
		} catch (e) {
			new Notice(`Checkpoint failed: ${(e as Error).message}`, 6000);
		}
	}

	private async exportPairs(): Promise<void> {
		try {
			const resp = await requestUrl({
				url:
					this.settings.brainUrl.replace(/\/$/, "") +
					"/brain/export-pairs?limit=500",
				method: "GET",
				throw: false,
			});
			if (resp.status >= 400) {
				new Notice(`Export failed: ${resp.status}`);
				return;
			}
			const folder = "Brain/Exports";
			if (!this.app.vault.getAbstractFileByPath(folder)) {
				await this.app.vault.createFolder(folder).catch(() => undefined);
			}
			const path = `${folder}/dpo-pairs-${Date.now()}.json`;
			await this.app.vault.create(path, JSON.stringify(resp.json, null, 2));
			new Notice(`Exported DPO pairs → ${path}`);
			void this.brain; // kept for parity with other modules
		} catch (e) {
			new Notice(`Export failed: ${(e as Error).message}`, 6000);
		}
	}
}

/*
 * Brain HTTP client — talks to the local RuVector brain server
 * (default 127.0.0.1:9876) and embedder (default 127.0.0.1:9877).
 */

import { requestUrl, RequestUrlResponse } from "obsidian";

export interface Memory {
	id: string;
	category: string;
	content?: string;
	content_hash: string;
	created_at: number;
	quality?: number;
	score?: number;
}

export interface SearchResponse {
	results: Memory[];
	query_vector_dim: number;
}

export interface BrainInfo {
	version: string;
	memories_count: number;
	preference_pairs_count: number;
	db_path: string;
	blob_dir: string;
}

export interface ScanResult {
	safe: boolean;
	threat_level: string;
	threats: string[];
}

export interface CreateMemoryResult {
	id: string;
	content_hash: string;
	created_at: number;
}

export class BrainError extends Error {
	constructor(
		public status: number,
		message: string,
		public body?: unknown,
	) {
		super(message);
		this.name = "BrainError";
	}
}

export class BrainClient {
	constructor(
		public brainUrl: string,
		public embedderUrl: string,
		private timeoutMs = 5000,
	) {}

	private async req<T>(
		method: string,
		path: string,
		body?: unknown,
		base?: string,
	): Promise<T> {
		const url = (base ?? this.brainUrl).replace(/\/$/, "") + path;
		let resp: RequestUrlResponse;
		try {
			resp = await requestUrl({
				url,
				method,
				contentType: "application/json",
				body: body !== undefined ? JSON.stringify(body) : undefined,
				throw: false,
			});
		} catch (e) {
			throw new BrainError(0, `network error: ${(e as Error).message}`);
		}
		if (resp.status >= 400) {
			throw new BrainError(resp.status, `${method} ${path} → ${resp.status}`, resp.json);
		}
		return resp.json as T;
	}

	async health(): Promise<{ status: string; version: string; backend: string }> {
		return this.req("GET", "/health");
	}

	async info(): Promise<BrainInfo> {
		return this.req("GET", "/brain/info");
	}

	async indexStats(): Promise<Record<string, unknown>> {
		return this.req("GET", "/brain/index_stats");
	}

	async search(query: string, k = 8): Promise<SearchResponse> {
		return this.req("POST", "/brain/search", { query, k });
	}

	async searchByVector(vector: number[], k = 8): Promise<SearchResponse> {
		return this.req("POST", "/brain/search", { query_vector: vector, k });
	}

	async createMemory(
		category: string,
		content: string,
		embedding?: number[],
	): Promise<CreateMemoryResult> {
		const body: Record<string, unknown> = { category, content };
		if (embedding && embedding.length) body.embedding = embedding;
		return this.req("POST", "/memories", body);
	}

	async getMemory(id: string): Promise<Memory> {
		return this.req("GET", `/memories/${id}`);
	}

	async listMemories(
		offset = 0,
		limit = 50,
		category?: string,
	): Promise<{ memories: Memory[]; total: number; count: number; offset: number }> {
		const q = new URLSearchParams({ offset: String(offset), limit: String(limit) });
		if (category) q.set("category", category);
		return this.req("GET", `/memories?${q.toString()}`);
	}

	async scan(text: string): Promise<ScanResult> {
		return this.req("POST", "/security/scan", { text });
	}

	async createPreferencePair(
		chosenId: string,
		rejectedId: string,
		direction: string,
	): Promise<{ id: string; created_at: number }> {
		return this.req("POST", "/preference_pairs", {
			chosen_id: chosenId,
			rejected_id: rejectedId,
			direction,
		});
	}

	async listPreferencePairs(
		limit = 20,
		direction?: string,
	): Promise<{ count: number; pairs: Array<Record<string, unknown>> }> {
		const q = new URLSearchParams({ limit: String(limit) });
		if (direction) q.set("direction", direction);
		return this.req("GET", `/preference_pairs?${q.toString()}`);
	}

	async embed(text: string): Promise<number[]> {
		const url = this.embedderUrl.replace(/\/$/, "") + "/embed";
		let resp: RequestUrlResponse;
		try {
			resp = await requestUrl({
				url,
				method: "POST",
				contentType: "application/json",
				body: JSON.stringify({ texts: [text] }),
				throw: false,
			});
		} catch (e) {
			throw new BrainError(0, `embedder network error: ${(e as Error).message}`);
		}
		if (resp.status >= 400) {
			throw new BrainError(resp.status, `embedder ${resp.status}`, resp.json);
		}
		const data = resp.json as { vectors?: number[][]; embeddings?: number[][] };
		const first = (data.vectors ?? data.embeddings)?.[0];
		if (!first) throw new BrainError(resp.status, "embedder returned no vector");
		return first;
	}
}

import { App, Modal, Notice, TFile, SuggestModal } from "obsidian";
import { BrainClient } from "./brain";
import type { BrainSettings } from "./settings";
import type { IndexState, Indexer } from "./indexer";

/**
 * DPO / preference pair workflow:
 *   1. User opens a note and runs "Mark current note as preferred (chosen)".
 *      We make sure the note is indexed, store the id in `heldChosen`.
 *   2. User opens a second note and runs "Create DPO pair with current note (rejected)".
 *      We index it too, POST the pair, and clear `heldChosen`.
 */
export class DpoController {
	heldChosen: { id: string; path: string } | null = null;

	constructor(
		private app: App,
		private brain: BrainClient,
		private indexer: Indexer,
		private settings: BrainSettings,
		private indexState: IndexState,
	) {}

	status(): string {
		return this.heldChosen ? `holding ${this.heldChosen.path}` : "empty";
	}

	async markChosen(): Promise<void> {
		const file = this.app.workspace.getActiveFile();
		if (!file || file.extension !== "md") {
			new Notice("Open a markdown note first");
			return;
		}
		const id = await this.ensureIndexed(file);
		if (!id) return;
		this.heldChosen = { id, path: file.path };
		new Notice(`Brain DPO: held '${file.name}' as chosen. Now open another and create the pair.`);
	}

	async clearChosen(): Promise<void> {
		this.heldChosen = null;
		new Notice("Brain DPO: cleared held chosen");
	}

	async createPairWithRejected(): Promise<void> {
		if (!this.heldChosen) {
			new Notice("Brain DPO: mark a chosen note first");
			return;
		}
		const file = this.app.workspace.getActiveFile();
		if (!file || file.extension !== "md") {
			new Notice("Open a markdown note first");
			return;
		}
		if (file.path === this.heldChosen.path) {
			new Notice("Brain DPO: chosen and rejected must differ");
			return;
		}
		const rejId = await this.ensureIndexed(file);
		if (!rejId) return;
		new DirectionPromptModal(this.app, this.settings.dpoDirection, async (direction) => {
			if (!direction) return;
			try {
				const pair = await this.brain.createPreferencePair(
					this.heldChosen!.id,
					rejId,
					direction,
				);
				new Notice(`Brain DPO: pair created (${pair.id.slice(0, 12)}, ${direction})`);
				this.heldChosen = null;
			} catch (e) {
				new Notice(`DPO pair failed: ${(e as Error).message}`, 8000);
			}
		}).open();
	}

	async exportPairs(): Promise<void> {
		try {
			const { pairs, count } = await this.brain.listPreferencePairs(500);
			const lines = [
				"# RuVector Brain — preference pairs export",
				"",
				`*count*: ${count}`,
				"",
				"| id | chosen | rejected | direction | created_at |",
				"| --- | --- | --- | --- | --- |",
				...pairs.map((p) => {
					const obj = p as Record<string, string | number>;
					return `| ${short(obj.id)} | ${short(obj.chosen_id)} | ${short(obj.rejected_id)} | ${obj.direction ?? ""} | ${obj.created_at ?? ""} |`;
				}),
			];
			const target = "Brain/Exports/preference-pairs.md";
			const folder = "Brain/Exports";
			if (!this.app.vault.getAbstractFileByPath(folder)) {
				await this.app.vault.createFolder(folder).catch(() => undefined);
			}
			const existing = this.app.vault.getAbstractFileByPath(target);
			if (existing instanceof TFile) {
				await this.app.vault.modify(existing, lines.join("\n"));
			} else {
				await this.app.vault.create(target, lines.join("\n"));
			}
			new Notice(`Brain DPO: exported ${count} pairs → ${target}`);
			void this.indexState;
		} catch (e) {
			new Notice(`DPO export failed: ${(e as Error).message}`, 8000);
		}
	}

	private async ensureIndexed(file: TFile): Promise<string | null> {
		const res = await this.indexer.indexFile(file, { force: false, notify: false });
		if (res.id) return res.id;
		// Already indexed: look up in state.
		const h = this.indexer.state.pathToHash[file.path];
		if (!h) {
			new Notice(`Brain DPO: '${file.name}' could not be indexed — ${res.reason}`);
			return null;
		}
		const existing = this.indexer.state.hashToId[h];
		return existing ?? null;
	}
}

function short(s: unknown): string {
	if (typeof s !== "string") return String(s ?? "");
	return s.slice(0, 12);
}

class DirectionPromptModal extends SuggestModal<string> {
	constructor(
		app: App,
		private defaultDir: string,
		private done: (dir: string | null) => void,
	) {
		super(app);
		this.setPlaceholder(`Direction (default: ${defaultDir})`);
	}

	getSuggestions(query: string): string[] {
		const base = new Set(["quality", "relevance", "recency", "tone", "clarity"]);
		if (this.defaultDir) base.add(this.defaultDir);
		if (query.trim()) base.add(query.trim());
		return Array.from(base);
	}

	renderSuggestion(value: string, el: HTMLElement): void {
		el.setText(value);
	}

	onChooseSuggestion(item: string): void {
		this.done(item);
	}

	onClose(): void {
		// If closed without choosing, surface a cancel to the caller.
		setTimeout(() => this.done(null), 0);
	}
}

export class DpoStatusModal extends Modal {
	constructor(
		app: App,
		private controller: DpoController,
	) {
		super(app);
	}

	onOpen(): void {
		const { contentEl } = this;
		contentEl.empty();
		contentEl.createEl("h2", { text: "DPO / preference pair state" });
		contentEl.createEl("p", { text: `Held chosen: ${this.controller.status()}` });
		const row = contentEl.createEl("div", { cls: "brain-dpo-buttons" });
		const clear = row.createEl("button", { text: "Clear held" });
		clear.onclick = () => {
			void this.controller.clearChosen();
			this.close();
		};
		const exp = row.createEl("button", { text: "Export pairs → vault", cls: "mod-cta" });
		exp.onclick = () => {
			void this.controller.exportPairs();
			this.close();
		};
	}

	onClose(): void {
		this.contentEl.empty();
	}
}

import { App, Notice, TFile } from "obsidian";
import type { BrainSettings } from "./settings";
import type { IndexState } from "./indexer";

interface ColorGroup {
	query: string;
	color: { a: number; rgb: number };
}

/**
 * Graph overlay — writes category color groups to `.obsidian/graph.json`
 * and ensures the configured notes carry a matching `#brain/<category>` tag.
 *
 * Obsidian doesn't expose a typed API for setting color groups at runtime,
 * so we edit the on-disk config. The user can revert at any time from
 * Obsidian → Graph view → color groups.
 */
export class GraphOverlay {
	constructor(
		private app: App,
		private indexState: IndexState,
		private settings: BrainSettings,
	) {}

	async apply(): Promise<void> {
		const byCategory = await this.collectCategories();
		if (byCategory.size === 0) {
			new Notice("Brain overlay: no indexed notes in this vault yet");
			return;
		}
		await this.tagNotes(byCategory);
		const groups = Array.from(byCategory.keys())
			.sort()
			.map<ColorGroup>((cat) => ({
				query: `tag:#brain/${safeTag(cat)}`,
				color: { a: 1, rgb: hashRgbInt(cat) },
			}));

		const graphPath = ".obsidian/graph.json";
		const adapter = this.app.vault.adapter;
		let existing: Record<string, unknown> = {};
		try {
			if (await adapter.exists(graphPath)) {
				const raw = await adapter.read(graphPath);
				existing = JSON.parse(raw) as Record<string, unknown>;
			}
		} catch (e) {
			console.warn("[obsidian-brain] graph.json unreadable", e);
		}
		const prior = Array.isArray(existing.colorGroups)
			? (existing.colorGroups as ColorGroup[]).filter(
					(g) => !(typeof g.query === "string" && g.query.startsWith("tag:#brain/")),
				)
			: [];
		existing.colorGroups = [...prior, ...groups];
		await adapter.write(graphPath, JSON.stringify(existing, null, 2));
		new Notice(
			`Brain overlay: ${groups.length} category color groups written to graph.json`,
		);
		void this.settings;
	}

	async clear(): Promise<void> {
		const adapter = this.app.vault.adapter;
		const graphPath = ".obsidian/graph.json";
		if (!(await adapter.exists(graphPath))) {
			new Notice("Brain overlay: no graph.json to clear");
			return;
		}
		const raw = await adapter.read(graphPath);
		const obj = JSON.parse(raw) as Record<string, unknown>;
		if (Array.isArray(obj.colorGroups)) {
			obj.colorGroups = (obj.colorGroups as ColorGroup[]).filter(
				(g) => !(typeof g.query === "string" && g.query.startsWith("tag:#brain/")),
			);
			await adapter.write(graphPath, JSON.stringify(obj, null, 2));
			new Notice("Brain overlay cleared");
		}
	}

	private async collectCategories(): Promise<Map<string, TFile[]>> {
		const out = new Map<string, TFile[]>();
		for (const [path] of Object.entries(this.indexState.pathToHash)) {
			const file = this.app.vault.getAbstractFileByPath(path);
			if (!(file instanceof TFile)) continue;
			const cache = this.app.metadataCache.getFileCache(file);
			let cat =
				(cache?.frontmatter?.["brain-category"] as string | undefined) ??
				(cache?.frontmatter?.["category"] as string | undefined) ??
				this.settings.defaultCategory;
			cat = (cat || "").trim() || this.settings.defaultCategory;
			const list = out.get(cat) ?? [];
			list.push(file);
			out.set(cat, list);
		}
		return out;
	}

	private async tagNotes(byCategory: Map<string, TFile[]>): Promise<void> {
		for (const [cat, files] of byCategory) {
			const tag = safeTag(cat);
			for (const file of files) {
				await this.app.fileManager
					.processFrontMatter(file, (fm) => {
						const tags = toTagArray(fm.tags);
						const marker = `brain/${tag}`;
						if (!tags.includes(marker)) tags.push(marker);
						fm.tags = tags;
					})
					.catch((e: unknown) => {
						console.warn("[obsidian-brain] tag failed", file.path, e);
					});
			}
		}
	}
}

function safeTag(s: string): string {
	return s.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "") || "general";
}

function toTagArray(v: unknown): string[] {
	if (Array.isArray(v)) return v.filter((x) => typeof x === "string") as string[];
	if (typeof v === "string") {
		return v
			.split(/[\s,]+/)
			.map((s) => s.replace(/^#/, ""))
			.filter(Boolean);
	}
	return [];
}

function hashRgbInt(s: string): number {
	let h = 0;
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
	const hue = Math.abs(h) % 360;
	const [r, g, b] = hslToRgb(hue / 360, 0.55, 0.55);
	return (r << 16) | (g << 8) | b;
}

function hslToRgb(h: number, s: number, l: number): [number, number, number] {
	const c = (1 - Math.abs(2 * l - 1)) * s;
	const x = c * (1 - Math.abs(((h * 6) % 2) - 1));
	const m = l - c / 2;
	let r = 0, g = 0, b = 0;
	if (h < 1 / 6) [r, g, b] = [c, x, 0];
	else if (h < 2 / 6) [r, g, b] = [x, c, 0];
	else if (h < 3 / 6) [r, g, b] = [0, c, x];
	else if (h < 4 / 6) [r, g, b] = [0, x, c];
	else if (h < 5 / 6) [r, g, b] = [x, 0, c];
	else [r, g, b] = [c, 0, x];
	return [
		Math.round((r + m) * 255),
		Math.round((g + m) * 255),
		Math.round((b + m) * 255),
	];
}

import { ItemView, TFile, WorkspaceLeaf } from "obsidian";
import { BrainClient, BrainError, Memory } from "./brain";
import type { BrainSettings } from "./settings";
import type { IndexState } from "./indexer";

export const RELATED_VIEW_TYPE = "obsidian-brain-related";

interface ViewState {
	loading: boolean;
	results: Memory[];
	error: string | null;
	sourcePath: string | null;
	selected: number;
}

export class RelatedView extends ItemView {
	private state: ViewState = {
		loading: false,
		results: [],
		error: null,
		sourcePath: null,
		selected: 0,
	};
	private generation = 0;
	private keyHandler: ((e: KeyboardEvent) => void) | null = null;

	constructor(
		leaf: WorkspaceLeaf,
		private brain: BrainClient,
		private settings: BrainSettings,
		private indexState: IndexState,
	) {
		super(leaf);
	}

	getViewType(): string {
		return RELATED_VIEW_TYPE;
	}

	getDisplayText(): string {
		return "Brain: related";
	}

	getIcon(): string {
		return "brain-circuit";
	}

	async onOpen(): Promise<void> {
		this.render();
		this.registerEvent(
			this.app.workspace.on("active-leaf-change", () => void this.refreshForActive()),
		);
		this.keyHandler = (e) => this.handleKey(e);
		this.contentEl.addEventListener("keydown", this.keyHandler);
		// Allow the view itself to receive focus for keyboard nav.
		this.contentEl.tabIndex = 0;
		await this.refreshForActive();
	}

	async onClose(): Promise<void> {
		this.generation++;
		if (this.keyHandler) {
			this.contentEl.removeEventListener("keydown", this.keyHandler);
			this.keyHandler = null;
		}
	}

	private handleKey(e: KeyboardEvent): void {
		if (this.state.results.length === 0) return;
		if (e.key === "ArrowDown" || e.key === "j") {
			e.preventDefault();
			this.state.selected = Math.min(
				this.state.results.length - 1,
				this.state.selected + 1,
			);
			this.render();
		} else if (e.key === "ArrowUp" || e.key === "k") {
			e.preventDefault();
			this.state.selected = Math.max(0, this.state.selected - 1);
			this.render();
		} else if (e.key === "Enter" || e.key === "o") {
			e.preventDefault();
			const r = this.state.results[this.state.selected];
			if (r) void this.activate(r);
		} else if (e.key === "r") {
			e.preventDefault();
			void this.refreshForActive();
		}
	}

	async refreshForActive(): Promise<void> {
		const file = this.app.workspace.getActiveFile();
		if (!file || file.extension !== "md") return;
		await this.loadForFile(file);
	}

	async loadForFile(file: TFile): Promise<void> {
		const gen = ++this.generation;
		this.state = {
			loading: true,
			results: [],
			error: null,
			sourcePath: file.path,
			selected: 0,
		};
		this.render();
		try {
			const raw = await this.app.vault.read(file);
			const body = raw.slice(0, 2000);
			const resp = await this.brain.search(body, this.settings.relatedLimit);
			if (gen !== this.generation) return;
			// Drop self-matches (same path we just asked about).
			const filtered = resp.results.filter((r) => {
				const path = this.indexState.idToPath[r.id];
				return path !== file.path;
			});
			this.state.results = filtered;
		} catch (e) {
			if (gen !== this.generation) return;
			this.state.error =
				e instanceof BrainError
					? `Brain ${e.status || "?"}: ${e.message}`
					: (e as Error).message;
		} finally {
			if (gen === this.generation) {
				this.state.loading = false;
				this.render();
			}
		}
	}

	private render(): void {
		const root = this.contentEl;
		root.empty();
		root.addClass("obsidian-brain-related-view");

		const header = root.createEl("div", { cls: "brain-related-header" });
		header.createEl("span", { cls: "brain-related-title", text: "Related memories" });
		const refresh = header.createEl("button", { cls: "clickable-icon", text: "↻" });
		refresh.ariaLabel = "Refresh";
		refresh.addEventListener("click", () => void this.refreshForActive());

		if (this.state.sourcePath) {
			root.createEl("div", {
				cls: "brain-related-source",
				text: this.state.sourcePath,
			});
		}
		if (this.state.loading) {
			root.createEl("div", { cls: "brain-related-status", text: "Searching brain…" });
			return;
		}
		if (this.state.error) {
			root.createEl("div", {
				cls: "brain-related-status brain-related-error",
				text: this.state.error,
			});
			return;
		}
		if (this.state.results.length === 0) {
			root.createEl("div", {
				cls: "brain-related-status",
				text: "No related memories. Try bulk-syncing your vault.",
			});
			return;
		}

		const list = root.createEl("div", { cls: "brain-related-list" });
		this.state.results.forEach((mem, idx) => {
			const row = list.createEl("div", {
				cls: `brain-related-row${idx === this.state.selected ? " selected" : ""}`,
			});
			const cat = row.createEl("span", {
				cls: "brain-related-category",
				text: mem.category,
			});
			cat.style.setProperty("--brain-category", hashColor(mem.category));
			const score = row.createEl("span", {
				cls: "brain-related-score",
				text: mem.score !== undefined ? mem.score.toFixed(3) : "",
			});
			void score;
			const snippet =
				(mem.content ?? "").replace(/\s+/g, " ").trim().slice(0, 180) ||
				mem.id.slice(0, 16);
			row.createEl("div", { cls: "brain-related-snippet", text: snippet });
			row.addEventListener("click", () => void this.activate(mem));
			row.addEventListener("mouseenter", () => {
				this.state.selected = idx;
				this.render();
			});
		});
		root.createEl("div", {
			cls: "brain-related-hint",
			text: "↑↓ or j/k move · Enter / o open · r refresh",
		});
	}

	private async activate(mem: Memory): Promise<void> {
		const path = this.indexState.idToPath[mem.id];
		if (path) {
			const file = this.app.vault.getAbstractFileByPath(path);
			if (file instanceof TFile) {
				await this.app.workspace.getLeaf(false).openFile(file);
				return;
			}
		}
		// Otherwise, prompt a temporary preview as a Notice.
		const content = mem.content
			? mem.content
			: (await this.brain.getMemory(mem.id)).content ?? "(no content)";
		const sample = content.slice(0, 400);
		const el = this.contentEl.createEl("div", { cls: "brain-related-preview" });
		el.createEl("pre").setText(sample);
		setTimeout(() => el.remove(), 12000);
	}
}

function hashColor(s: string): string {
	let h = 0;
	for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) | 0;
	const hue = Math.abs(h) % 360;
	return `hsl(${hue}, 55%, 55%)`;
}
